import Foundation
import Testing
@testable import MLXUI

/// PF-6, Trap 5 — the constrained BIOES Viterbi decoder and the label space.
///
/// The pure cases below use log-probability matrices and expected label paths generated by the
/// pinned reference (`opf` commit `f7f00ca…`, `ViterbiCRFDecoder` with
/// `build_label_info(NER_CLASS_NAMES_BY_CATEGORY_VERSION["v2"])`; default and one non-zero
/// calibration). They run without a checkpoint. The corpus suite decodes the checked-in
/// `log_probs` fixtures, so a failure says whether the decode half or the tokenizer/network half is
/// wrong.
struct PrivacyFilterDecoderTests {

    // MARK: - Helpers

    /// Deterministic fp32 log-probability rows used by the embedded reference cases:
    /// `row(t, k) = ((t*31 + k*7) mod 17 - 8) / 8` — exact binary fractions, so Swift and the
    /// reference build the same fp32 values without decimal-rounding drift.
    private static func formulaRows(_ sequenceLength: Int) -> [[Float]] {
        (0 ..< sequenceLength).map { step in
            (0 ..< 33).map { label in
                Float(((step * 31 + label * 7) % 17) - 8) / 8.0
            }
        }
    }

    /// Sharp rows for a chosen BIOES path: 2.0 on the chosen label, -3.0 elsewhere.
    private static func peakedRows(_ path: [String]) -> [[Float]] {
        let names = PrivacyFilterLabelInfo.canonicalLabelNames
        return path.map { name in
            var row = [Float](repeating: -3.0, count: 33)
            if let index = names.firstIndex(of: name) { row[index] = 2.0 }
            return row
        }
    }

    private func decoder(_ calibration: PrivacyFilterCalibration = .zero) -> PrivacyFilterDecoder {
        PrivacyFilterDecoder(labelInfo: .standard, calibration: calibration)
    }

    // MARK: - Label space (`opf/_core/sequence_labeling.py::build_label_info`)

    @Test func labelSpaceHasThirtyThreeBIOESLabelsAndEightCategories() {
        let info = PrivacyFilterLabelInfo.standard
        #expect(info.classNames == PrivacyFilterLabelInfo.canonicalLabelNames)
        #expect(info.classNames.count == 33)
        #expect(info.classNames.first == "O")
        #expect(info.backgroundTokenLabel == 0)
        #expect(info.backgroundSpanLabel == 0)
        #expect(info.spanClassNames == [
            "O", "account_number", "private_address", "private_date", "private_email",
            "private_person", "private_phone", "private_url", "secret",
        ])
        #expect(info.tokenToSpanLabel.count == 33)
        #expect(info.tokenBoundaryTags.count == 32)
        #expect(Set(info.spanLabelCategories.compactMap { $0 }) == Set(PrivacyFilterCategory.allCases))
    }

    @Test func labelSpaceMapsEachCategoryAndBoundaryToItsTokenLabel() {
        let info = PrivacyFilterLabelInfo.standard
        for category in PrivacyFilterCategory.allCases {
            for boundary in ["B", "I", "E", "S"] {
                let tokenLabel = info.tokenLabelID(category: category, boundary: boundary)
                #expect(tokenLabel != nil, "\(category.rawValue)-\(boundary) is missing")
                #expect(info.tokenBoundaryTags[tokenLabel ?? -1] == boundary)
                #expect(info.category(forTokenLabel: tokenLabel ?? -1) == category)
            }
        }
        // A one-token span decodes to its category; background decodes to nothing.
        #expect(info.category(forTokenLabel: 20) == .person)   // S-private_person
        #expect(info.category(forTokenLabel: 16) == .email)    // S-private_email
        #expect(info.category(forTokenLabel: 24) == .phone)    // S-private_phone
        #expect(info.category(forTokenLabel: 28) == .url)      // S-private_url
        #expect(info.category(forTokenLabel: 8) == .address)   // S-private_address
        #expect(info.category(forTokenLabel: 12) == .date)     // S-private_date
        #expect(info.category(forTokenLabel: 4) == .account)   // S-account_number
        #expect(info.category(forTokenLabel: 32) == .secret)   // S-secret
        #expect(info.category(forTokenLabel: 0) == nil)
    }

    @Test func categoryPlaceholdersMatchTheReference() {
        #expect(PrivacyFilterCategory.person.placeholder == "<PRIVATE_PERSON>")
        #expect(PrivacyFilterCategory.email.placeholder == "<PRIVATE_EMAIL>")
        #expect(PrivacyFilterCategory.phone.placeholder == "<PRIVATE_PHONE>")
        #expect(PrivacyFilterCategory.url.placeholder == "<PRIVATE_URL>")
        #expect(PrivacyFilterCategory.address.placeholder == "<PRIVATE_ADDRESS>")
        #expect(PrivacyFilterCategory.date.placeholder == "<PRIVATE_DATE>")
        #expect(PrivacyFilterCategory.account.placeholder == "<ACCOUNT_NUMBER>")
        #expect(PrivacyFilterCategory.secret.placeholder == "<SECRET>")
        #expect(PrivacyFilterCategory.allCases.map(\.modelLabel) == [
            "private_person", "private_email", "private_phone", "private_url",
            "private_address", "private_date", "account_number", "secret",
        ])
    }

    @Test func labelSpaceRefusesMalformedLabelLists() {
        #expect(throws: PrivacyFilterLabelError.self) {
            _ = try PrivacyFilterLabelInfo(classNames: ["O", "B-private_person"])
        }
        #expect(throws: PrivacyFilterLabelError.self) {
            _ = try PrivacyFilterLabelInfo(classNames: ["B-private_person"])
        }
        #expect(throws: PrivacyFilterLabelError.self) {
            _ = try PrivacyFilterLabelInfo(classNames: ["O", "X-private_person"])
        }
        #expect(throws: PrivacyFilterLabelError.self) {
            _ = try PrivacyFilterLabelInfo(classNames: ["O", "O"])
        }
    }

    // MARK: - Embedded reference paths (opf ViterbiCRFDecoder)

    @Test func decodesTheReferenceFormulaPath() {
        #expect(decoder().decode(logProbs: Self.formulaRows(12))
                == [12, 0, 8, 8, 4, 4, 0, 32, 8, 28, 4, 24])
    }

    @Test func tiesResolveToTheFirstLabelLikeTorchMax() {
        let zeros = [[Float]](repeating: [Float](repeating: 0, count: 33), count: 10)
        #expect(decoder().decode(logProbs: zeros) == [Int](repeating: 0, count: 10))
    }

    @Test func noFiniteScoresFallsBackToPerTokenArgmax() {
        let negativeInfinity = [[Float]](
            repeating: [Float](repeating: -Float.infinity, count: 33), count: 6)
        #expect(decoder().decode(logProbs: negativeInfinity) == [Int](repeating: 0, count: 6))
        #expect(PrivacyFilterDecoder.argmaxPath(negativeInfinity, numClasses: 33)
                == [Int](repeating: 0, count: 6))
    }

    @Test func decodesTheReferenceDesignedBIOESPath() {
        let path = [
            "O", "B-private_person", "I-private_person", "E-private_person", "O",
            "S-private_email", "B-private_phone", "E-private_phone", "O",
            "B-secret", "I-secret", "E-secret", "O",
        ]
        #expect(decoder().decode(logProbs: Self.peakedRows(path)) == [0, 17, 18, 19, 0, 16, 21, 23, 0, 29, 30, 31, 0])
    }

    @Test func constraintsOverrideAnImpossibleEmissionPath() {
        // B then S of different labels: the CRF cannot follow the emissions, and opf's path is O at
        // that token rather than an invalid transition.
        let path = ["O", "B-private_person", "S-private_email", "I-private_email", "O"]
        #expect(decoder().decode(logProbs: Self.peakedRows(path)) == [0, 0, 16, 0, 0])
    }

    @Test func calibrationBiasesChangeTheReferencePath() {
        let calibration = PrivacyFilterCalibration(
            transitionBiasBackgroundStay: -2.0,
            transitionBiasBackgroundToStart: 1.5,
            transitionBiasInsideToContinue: 0.25,
            transitionBiasInsideToEnd: -0.5,
            transitionBiasEndToBackground: -1.0,
            transitionBiasEndToStart: 0.75)
        #expect(decoder(calibration).decode(logProbs: Self.formulaRows(12))
                == [12, 12, 8, 8, 4, 4, 12, 32, 8, 28, 4, 24])
    }

    @Test func decodingIsDeterministic() {
        let rows = Self.formulaRows(40)
        let first = decoder().decode(logProbs: rows)
        let second = decoder().decode(logProbs: rows)
        #expect(first == second)
        // Determinism must not depend on the caller's order of independent decoders either.
        #expect(decoder().decode(logProbs: rows) == first)
    }

    @Test func emptyMatrixDecodesToNoLabels() {
        #expect(decoder().decode(logProbs: []) == [])
    }

    @Test func scoreRowCountMismatchFallsBackToArgmax() {
        // Defensive path: rows of the wrong width go through argmax instead of out-of-bounds.
        let rows: [[Float]] = [[1, 0], [0, 1]]
        #expect(decoder().decode(logProbs: rows) == [0, 1])
    }

    // MARK: - Calibration file

    private static let zeroCalibrationJSON = """
    {
      "operating_points": {
        "default": {
          "biases": {
            "transition_bias_background_stay": 0.0,
            "transition_bias_background_to_start": 0.0,
            "transition_bias_inside_to_continue": 0.0,
            "transition_bias_inside_to_end": 0.0,
            "transition_bias_end_to_background": 0.0,
            "transition_bias_end_to_start": 0.0
          }
        }
      }
    }
    """

    private func temporaryDirectory() throws -> URL {
        let url = FileManager.default.temporaryDirectory
            .appendingPathComponent("pf-calibration-\(UUID().uuidString)")
        try FileManager.default.createDirectory(at: url, withIntermediateDirectories: true)
        return url
    }

    @Test func zeroIsAllZero() {
        let zero = PrivacyFilterCalibration.zero
        #expect(zero.transitionBiasBackgroundStay == 0)
        #expect(zero.transitionBiasBackgroundToStart == 0)
        #expect(zero.transitionBiasInsideToContinue == 0)
        #expect(zero.transitionBiasInsideToEnd == 0)
        #expect(zero.transitionBiasEndToBackground == 0)
        #expect(zero.transitionBiasEndToStart == 0)
    }

    @Test func loadsTheShippedCalibrationShape() throws {
        let directory = try temporaryDirectory()
        defer { try? FileManager.default.removeItem(at: directory) }
        try Data(Self.zeroCalibrationJSON.utf8)
            .write(to: directory.appendingPathComponent(PrivacyFilterCalibration.filename))
        #expect(try PrivacyFilterCalibration.load(from: directory) == .zero)
    }

    @Test func missingCalibrationFileRefusesWithOneSentence() throws {
        let directory = try temporaryDirectory()
        defer { try? FileManager.default.removeItem(at: directory) }
        do {
            _ = try PrivacyFilterCalibration.load(from: directory)
            Issue.record("a folder without viterbi_calibration.json was accepted")
        } catch let error as PrivacyFilterCalibrationError {
            #expect(error == .missingFile)
            #expect(error.errorDescription?.contains("viterbi_calibration.json") == true)
        }
    }

    @Test func malformedCalibrationIsRefusedRatherThanHalfApplied() throws {
        let directory = try temporaryDirectory()
        defer { try? FileManager.default.removeItem(at: directory) }
        let url = directory.appendingPathComponent(PrivacyFilterCalibration.filename)
        // Extra key.
        try Data(Self.zeroCalibrationJSON
            .replacingOccurrences(of: "\"transition_bias_end_to_start\": 0.0",
                                  with: "\"transition_bias_end_to_start\": 0.0, \"extra\": 0.0")
            .utf8).write(to: url)
        #expect(throws: PrivacyFilterCalibrationError.self) {
            _ = try PrivacyFilterCalibration.load(from: directory)
        }
        // Non-numeric bias.
        try Data(Self.zeroCalibrationJSON
            .replacingOccurrences(of: "\"transition_bias_end_to_start\": 0.0",
                                  with: "\"transition_bias_end_to_start\": \"zero\"")
            .utf8).write(to: url)
        #expect(throws: PrivacyFilterCalibrationError.self) {
            _ = try PrivacyFilterCalibration.load(from: directory)
        }
    }

    // MARK: - Corpus: fixture log-probs → fixture spans (opt-in)

    @Suite(.enabled(
        if: PrivacyFilterDecodeTestSupport.canRunFixtures,
        "needs MLXUI_TEST_PRIVACY=1 and the checked-in fixtures"))
    struct FixtureDecoderTests {

        /// Decoder + span math, isolated from the tokenizer: consume the checked-in `log_probs`
        /// rows and compare the selected spans with `opf`'s.
        @Test func fixtureLogProbsDecodeToTheFixtureSpans() throws {
            let golden = try PrivacyFilterDecodeTestSupport.loadGolden()
            var cases = PrivacyFilterDecodeTestSupport.shortCases(golden).map { (name: $0.name, value: $0.value) }
            if let longDocument = golden.long_document { cases.append((name: "long_document", value: longDocument)) }
            let decoder = PrivacyFilterDecoder(labelInfo: .standard, calibration: .zero)
            var checked = 0
            for (name, testCase) in cases {
                guard let logProbsFile = testCase.log_probs else { continue }
                let logProbs = try PrivacyFilterDecodeTestSupport.floatRows(logProbsFile)
                #expect(!testCase.decoded_mismatch, "\(name): reference decoded a different text")
                let tokenization = PrivacyFilterDecodeTestSupport.tokenization(for: testCase)
                let spans = try PrivacyFilterRedactor.detectedSpans(
                    testCase.text, logProbs: logProbs, tokenization: tokenization, decoder: decoder)
                #expect(spans.count == testCase.spans.count,
                        "\(name): \(spans.count) spans vs \(testCase.spans.count)")
                if spans.count == testCase.spans.count {
                    for (span, expected) in zip(spans, testCase.spans) {
                        #expect(span.category.modelLabel == expected.label, "\(name): label")
                        #expect(span.utf8Start == expected.start_byte, "\(name): start byte")
                        #expect(span.utf8End == expected.end_byte, "\(name): end byte")
                        #expect(span.text == expected.text, "\(name): covered text")
                    }
                }
                checked += 1
            }
            print("PF6 decoder-on-fixture-logprobs: \(checked)/\(cases.count) corpus texts give opf's spans")
            PrivacyFilterDecodeTestSupport.record("PF6 decoder-on-fixture-logprobs: \(checked)/\(cases.count) corpus texts give opf's spans")
        }

        @Test func decodingTwiceGivesIdenticalLabels() throws {
            let golden = try PrivacyFilterDecodeTestSupport.loadGolden()
            let decoder = PrivacyFilterDecoder(labelInfo: .standard, calibration: .zero)
            let testCase = try #require(PrivacyFilterDecodeTestSupport.shortCases(golden).first(where: {
                $0.value.log_probs != nil && $0.value.token_ids.count > 4
            })?.value)
            let logProbs = try PrivacyFilterDecodeTestSupport.floatRows(
                try #require(testCase.log_probs))
            let first = decoder.decode(logProbs: logProbs)
            let second = decoder.decode(logProbs: logProbs)
            #expect(first == second)
            #expect(first.count == testCase.token_ids.count)
        }
    }
}
